/**
 * The Qwik side of the tool catalog: one component per catalog entry, and a
 * renderer that picks by `type`. json-render ships renderers for React, Vue,
 * Svelte and Solid; this is the same contract — spec in, components out — for
 * Qwik, and it only ever sees specs `validateToolSpec` has already passed.
 */
import { component$, useSignal, useStore } from "@qwik.dev/core";
import { NumericStepper } from "../ui/numeric-stepper";
import { inFlowController } from "../editor/extensions/struggle-tracker";
import type { ActiveTool } from "../../utils/in-flow-tools";
import type { SavedToolConfig } from "../../utils/saved-tools";
import type {
  ClaimCheckProps,
  ReaderQuestionsProps,
  RhythmStripProps,
  SentenceLabProps,
} from "./catalog";

/** What "Keep this tool" should remember about the tool as the writer left it. */
export function configFor(tool: ActiveTool): SavedToolConfig {
  const element = tool.spec.elements.tool;
  switch (element.type) {
    case "RhythmStrip":
      return {
        targetMin: element.props.targetMin,
        targetMax: element.props.targetMax,
      };
    case "ClaimCheck":
      return { slots: element.props.slots.map((slot) => slot.label) };
    case "ReaderQuestions":
      return element.props.angle ? { angle: element.props.angle } : {};
    default:
      return {};
  }
}

export const ToolRenderer = component$<{ tool: ActiveTool }>(({ tool }) => {
  const element = tool.spec.elements.tool;
  switch (element.type) {
    case "SentenceLab":
      return (
        <SentenceLab
          key={tool.id}
          props={element.props}
          filling={tool.status === "filling"}
        />
      );
    case "RhythmStrip":
      return <RhythmStrip key={tool.id} props={element.props} />;
    case "ClaimCheck":
      return <ClaimCheck key={tool.id} props={element.props} />;
    case "ReaderQuestions":
      return (
        <ReaderQuestions
          key={tool.id}
          props={element.props}
          filling={tool.status === "filling"}
        />
      );
  }
});

/* ── Sentence Lab ──────────────────────────────────────────────── */

/**
 * The writer's own attempts beside fresh ones. Clicking any line loads it into
 * a working copy they can edit before it replaces the sentence — so mixing
 * the start of one attempt with the end of another is just typing.
 */
const SentenceLab = component$<{ props: SentenceLabProps; filling: boolean }>(
  ({ props, filling }) => {
    const working = useSignal(props.sentence);
    const Row = ({ text, label }: { text: string; label: string }) => (
      <li>
        <button
          type="button"
          class={[
            "in-flow-choice",
            { "in-flow-choice--on": working.value === text },
          ]}
          onClick$={() => {
            working.value = text;
          }}
          title={`Load this ${label} into the working copy`}
        >
          {text}
        </button>
      </li>
    );
    return (
      <div class="in-flow-body">
        {props.attempts.length > 0 && (
          <section>
            <p class="in-flow-label">Your earlier tries</p>
            <ol class="in-flow-list">
              {props.attempts.map((text) => (
                <Row key={`a-${text}`} text={text} label="attempt" />
              ))}
            </ol>
          </section>
        )}
        <section>
          <p class="in-flow-label">Other ways</p>
          <ol class="in-flow-list">
            {props.variants.map((text) => (
              <Row key={`v-${text}`} text={text} label="variant" />
            ))}
          </ol>
          {filling && (
            <p class="in-flow-quiet" role="status">
              Finding other wordings…
            </p>
          )}
        </section>
        <section>
          <label class="in-flow-label" for="in-flow-working">
            Working copy
          </label>
          <textarea
            id="in-flow-working"
            class="in-flow-textarea"
            rows={3}
            value={working.value}
            onInput$={(_, el) => {
              working.value = el.value;
            }}
          />
          <div class="in-flow-actions">
            <button
              type="button"
              class="btn-press"
              disabled={
                !working.value.trim() || working.value === props.sentence
              }
              onClick$={() =>
                inFlowController()?.applyVariant(working.value.trim())
              }
            >
              Use this
            </button>
            <span class="in-flow-quiet">Undo puts yours back.</span>
          </div>
        </section>
      </div>
    );
  },
);

/* ── Rhythm Strip ──────────────────────────────────────────────── */

const RhythmStrip = component$<{ props: RhythmStripProps }>(({ props }) => {
  // The band lives in the spec (the controller re-seeds it), so a kept tool
  // remembers exactly the band the writer settled on.
  const band = { min: props.targetMin, max: props.targetMax };
  const scale = Math.max(
    band.max * 1.4,
    ...props.sentences.map((s) => s.words),
  );
  const long = props.sentences.filter((s) => s.words > band.max).length;
  const short = props.sentences.filter((s) => s.words < band.min).length;
  const lengths = props.sentences.map((s) => s.words);
  const flat =
    lengths.length >= 4 && Math.max(...lengths) - Math.min(...lengths) <= 4;
  const summary = flat
    ? "The sentences are all about the same length."
    : long || short
      ? [
          long && `${long} run${long === 1 ? "s" : ""} long`,
          short && `${short} ${short === 1 ? "is" : "are"} clipped`,
        ]
          .filter(Boolean)
          .join(", ") + "."
      : "The lengths vary within the band.";
  return (
    <div
      class="in-flow-body"
      data-rhythm-min={band.min}
      data-rhythm-max={band.max}
    >
      <p class="in-flow-summary">{summary}</p>
      <ol class="in-flow-rhythm" aria-label="Sentence lengths">
        {props.sentences.map((s, i) => {
          const tone =
            s.words > band.max ? "long" : s.words < band.min ? "short" : "fit";
          return (
            <li key={`${i}-${s.words}`}>
              <button
                type="button"
                class={`in-flow-bar in-flow-bar--${tone}`}
                style={{ "--bar": `${(s.words / scale) * 100}%` }}
                onMouseEnter$={() => inFlowController()?.highlightSentence(i)}
                onFocus$={() => inFlowController()?.highlightSentence(i)}
                onMouseLeave$={() =>
                  inFlowController()?.highlightSentence(null)
                }
                onBlur$={() => inFlowController()?.highlightSentence(null)}
                onClick$={() => inFlowController()?.selectSentence(i)}
                title={s.text}
                aria-label={`Sentence ${i + 1}: ${s.words} words. Select it in the draft.`}
              >
                <span class="in-flow-bar__fill" />
                <span class="in-flow-bar__count">{s.words}</span>
              </button>
            </li>
          );
        })}
      </ol>
      <div class="in-flow-row in-flow-band">
        <span class="in-flow-label">Comfortable length</span>
        <NumericStepper
          value={band.min}
          min={1}
          max={band.max - 1}
          density="compact"
          ariaLabel="Shortest comfortable sentence, in words"
          onValue$={(value) => {
            if (value !== null)
              inFlowController()?.setRhythmBand(value, band.max);
          }}
        />
        <span aria-hidden="true">–</span>
        <NumericStepper
          value={band.max}
          min={band.min + 1}
          max={120}
          density="compact"
          suffix=" words"
          ariaLabel="Longest comfortable sentence, in words"
          onValue$={(value) => {
            if (value !== null)
              inFlowController()?.setRhythmBand(band.min, value);
          }}
        />
      </div>
      <p class="in-flow-quiet">
        Hover a bar to find its sentence; click to select it.
      </p>
    </div>
  );
});

/* ── Claim Check ───────────────────────────────────────────────── */

const SLOT_HINT: Record<string, string> = {
  "A source": "Who else says so? The Apparatus can look.",
  "An example": "One concrete case, right after the claim.",
  "A number": "A figure, and where it comes from.",
};

const ClaimCheck = component$<{ props: ClaimCheckProps }>(({ props }) => {
  const state = useStore({
    slots: props.slots.map((slot) => ({ ...slot })),
    adding: "",
    message: "",
    searching: false,
  });
  const open = state.slots.filter((slot) => !slot.filled).length;
  return (
    <div class="in-flow-body">
      <blockquote class="in-flow-claim">{props.claim}</blockquote>
      <p class="in-flow-summary">
        {open === 0
          ? "Every kind of support you asked for is here."
          : `${open} kind${open === 1 ? "" : "s"} of support still missing.`}
      </p>
      <ul class="in-flow-slots">
        {state.slots.map((slot, i) => (
          <li key={slot.label} class={{ "is-filled": slot.filled }}>
            <label class="in-flow-slot">
              <input
                type="checkbox"
                checked={slot.filled}
                onChange$={(_, el) => {
                  state.slots[i].filled = el.checked;
                }}
              />
              <span>
                <strong>{slot.label}</strong>
                {!slot.filled && SLOT_HINT[slot.label] && (
                  <span class="in-flow-quiet"> — {SLOT_HINT[slot.label]}</span>
                )}
              </span>
            </label>
            {!slot.filled && slot.label === "A source" && (
              <button
                type="button"
                class="btn-paper in-flow-mini"
                disabled={state.searching}
                onClick$={async () => {
                  state.searching = true;
                  state.message = "";
                  const error =
                    (await inFlowController()?.research(props.claim)) ?? null;
                  state.searching = false;
                  state.message =
                    error ?? "Searching — results land in the Apparatus.";
                }}
              >
                {state.searching ? "Looking…" : "Find"}
              </button>
            )}
          </li>
        ))}
      </ul>
      <input
        class="in-flow-input"
        placeholder="Another kind of support…"
        value={state.adding}
        onInput$={(_, el) => {
          state.adding = el.value;
        }}
        onKeyDown$={(event) => {
          const label = state.adding.trim().slice(0, 60);
          if (event.key !== "Enter" || !label) return;
          if (state.slots.length >= 5) return;
          if (!state.slots.some((slot) => slot.label === label))
            state.slots.push({ label, filled: false });
          state.adding = "";
        }}
        aria-label="Add a kind of support"
      />
      {state.message && (
        <p class="in-flow-quiet" role="status">
          {state.message}
        </p>
      )}
    </div>
  );
});

/* ── Reader Questions ──────────────────────────────────────────── */

const ReaderQuestions = component$<{
  props: ReaderQuestionsProps;
  filling: boolean;
}>(({ props, filling }) => {
  const state = useStore({
    angle: props.angle,
    answered: [] as string[],
    jotted: [] as string[],
  });
  return (
    <div class="in-flow-body">
      <label class="in-flow-label" for="in-flow-angle">
        Reading as
      </label>
      <div class="in-flow-row">
        <input
          id="in-flow-angle"
          class="in-flow-input"
          placeholder="the piece's intended reader"
          value={state.angle}
          onInput$={(_, el) => {
            state.angle = el.value;
          }}
          onKeyDown$={(event) => {
            if (event.key === "Enter") inFlowController()?.reask(state.angle);
          }}
        />
        <button
          type="button"
          class="btn-paper in-flow-mini"
          disabled={filling || state.angle === props.angle}
          onClick$={() => inFlowController()?.reask(state.angle)}
        >
          Ask
        </button>
      </div>
      <ol class="in-flow-list">
        {props.questions.map((question) => {
          const answered = state.answered.includes(question);
          const jotted = state.jotted.includes(question);
          return (
            <li
              key={question}
              class={["in-flow-question", { "is-answered": answered }]}
            >
              <label class="in-flow-slot">
                <input
                  type="checkbox"
                  checked={answered}
                  onChange$={(_, el) => {
                    state.answered = el.checked
                      ? [...state.answered, question]
                      : state.answered.filter((q) => q !== question);
                  }}
                />
                <span>{question}</span>
              </label>
              <button
                type="button"
                class="btn-paper in-flow-mini"
                disabled={jotted}
                title="Save this question to your scraps"
                onClick$={async () => {
                  if (await inFlowController()?.jot(question))
                    state.jotted = [...state.jotted, question];
                }}
              >
                {jotted ? "Jotted" : "Jot"}
              </button>
            </li>
          );
        })}
      </ol>
      {filling && (
        <p class="in-flow-quiet" role="status">
          Imagining the reader…
        </p>
      )}
    </div>
  );
});

src/components/in-flow/margin-rail.tsx.content:
/**
 * The margins, used the way Google Docs uses them.
 *
 * Right margin: the one live tool, pinned level with the passage it is about
 * and joined to it by a hairline, so it reads as a note on *that* passage.
 * Left margin: "Your tools" — the tools the writer kept — and a faint tick
 * beside each paragraph they have been working hard at.
 *
 * Both rails sit inside the page canvas, so they scroll with the page. When
 * the window is too narrow to give a margin room, the rails step aside: the
 * tool opens as a card under its passage instead and the shelf folds away.
 */
import {
  $,
  component$,
  useSignal,
  useStore,
  useVisibleTask$,
} from "@qwik.dev/core";
import {
  inFlowController,
  inFlowSnapshot,
} from "../editor/extensions/struggle-tracker";
import {
  IN_FLOW_EVENT,
  type ActiveTool,
  type InFlowSnapshot,
} from "../../utils/in-flow-tools";
import {
  loadSavedTools,
  removeSavedTool,
  SAVED_TOOLS_EVENT,
  type SavedTool,
} from "../../utils/saved-tools";
import { TOOL_LABELS } from "../../utils/struggle-signals";
import { configFor, ToolRenderer } from "./tool-renderer";

const CARD_WIDTH = 296;
const RAIL_GAP = 28;
const SHELF_WIDTH = 176;

interface RailState {
  active: ActiveTool | null;
  /** Card top relative to the canvas, or null before measuring. */
  cardTop: number | null;
  /** Passage top/height relative to the canvas, for the connector. */
  anchorTop: number;
  anchorHeight: number;
  ticks: number[];
  mode: "rail" | "popover";
  shelf: boolean;
  /** Popover mode: fixed viewport position. */
  popLeft: number;
  popTop: number;
  saved: SavedTool[];
  naming: boolean;
  name: string;
  keepError: string;
}

export const MarginRails = component$<{ zen: boolean; readOnly?: boolean }>(
  (props) => {
    const root = useSignal<HTMLDivElement>();
    const state = useStore<RailState>({
      active: null,
      cardTop: null,
      anchorTop: 0,
      anchorHeight: 0,
      ticks: [],
      mode: "rail",
      shelf: true,
      popLeft: 0,
      popTop: 0,
      saved: [],
      naming: false,
      name: "",
      keepError: "",
    });

    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(({ cleanup }) => {
      const el = root.value;
      const canvas = el?.closest<HTMLElement>(".page-canvas");
      const scroller = canvas?.parentElement;
      if (!el || !canvas || !scroller) return;
      let tickPositions: number[] = [];
      let frame = 0;

      const measure = () => {
        cancelAnimationFrame(frame);
        frame = requestAnimationFrame(() => {
          const canvasRect = canvas.getBoundingClientRect();
          const scrollerRect = scroller.getBoundingClientRect();
          const right = scrollerRect.right - canvasRect.right;
          const left = canvasRect.left - scrollerRect.left;
          state.mode = right >= CARD_WIDTH + RAIL_GAP + 8 ? "rail" : "popover";
          state.shelf = left >= SHELF_WIDTH + RAIL_GAP;

          const controller = inFlowController();
          const rect = state.active ? controller?.anchorRect() : null;
          if (rect) {
            state.anchorTop = rect.top - canvasRect.top;
            state.anchorHeight = rect.height;
            state.cardTop = Math.max(0, state.anchorTop - 6);
            state.popLeft = Math.max(
              12,
              Math.min(rect.left, window.innerWidth - CARD_WIDTH - 12),
            );
            state.popTop = Math.max(
              12,
              Math.min(rect.bottom + 10, window.innerHeight - 120),
            );
          } else {
            state.cardTop = null;
          }
          state.ticks = tickPositions
            .map((pos) => controller?.blockTop(pos))
            .filter((top): top is number => typeof top === "number")
            .map((top) => top - canvasRect.top);
        });
      };

      const onSnapshot = (detail: InFlowSnapshot) => {
        // Plain copies only: the snapshot is shared module state.
        state.active = detail.active
          ? (JSON.parse(JSON.stringify(detail.active)) as ActiveTool)
          : null;
        if (!detail.active) {
          state.naming = false;
          state.keepError = "";
        }
        tickPositions = detail.ticks;
        measure();
      };
      const onEvent = (event: Event) =>
        onSnapshot((event as CustomEvent<InFlowSnapshot>).detail);
      const onSaved = (event: Event) => {
        state.saved = (event as CustomEvent<SavedTool[]>).detail ?? [];
      };

      onSnapshot(inFlowSnapshot());
      void loadSavedTools().then((tools) => {
        state.saved = tools;
      });
      window.addEventListener(IN_FLOW_EVENT, onEvent);
      window.addEventListener(SAVED_TOOLS_EVENT, onSaved);
      window.addEventListener("twyne:content", measure);
      window.addEventListener("resize", measure);
      // The popover is fixed to the viewport, so it must follow a scroll.
      const onScroll = () => {
        if (state.active && state.mode === "popover") measure();
      };
      scroller.addEventListener("scroll", onScroll, { passive: true });
      const observer = new ResizeObserver(measure);
      observer.observe(canvas);
      observer.observe(scroller);
      cleanup(() => {
        cancelAnimationFrame(frame);
        window.removeEventListener(IN_FLOW_EVENT, onEvent);
        window.removeEventListener(SAVED_TOOLS_EVENT, onSaved);
        window.removeEventListener("twyne:content", measure);
        window.removeEventListener("resize", measure);
        scroller.removeEventListener("scroll", onScroll);
        observer.disconnect();
      });
    });

    const keep = $(async () => {
      const tool = state.active;
      if (!tool) return;
      const name = state.name.trim() || TOOL_LABELS[tool.kind];
      try {
        await inFlowController()?.keep(name, configFor(tool));
        state.naming = false;
        state.keepError = "";
      } catch {
        state.keepError = "Couldn't keep it — storage refused the write.";
      }
    });

    if (props.zen || props.readOnly) return <div ref={root} hidden />;

    const tool = state.active;
    const card = tool && (
      <article
        class={[
          "in-flow-card",
          { "in-flow-card--filling": tool.status === "filling" },
        ]}
        aria-label={`${TOOL_LABELS[tool.kind]} for this passage`}
      >
        <header class="in-flow-card__head">
          <button
            type="button"
            class="in-flow-card__title"
            onClick$={() => inFlowController()?.focusAnchor()}
            title="Go to the passage"
          >
            {TOOL_LABELS[tool.kind]}
          </button>
          {tool.tentative && (
            <span
              class="in-flow-card__maybe"
              title="The signals were mixed; ignore this if it doesn't fit."
            >
              maybe
            </span>
          )}
          <button
            type="button"
            class="in-flow-card__close"
            onClick$={() => inFlowController()?.dismiss()}
            aria-label="Dismiss this tool"
            title="Dismiss — this passage stays quiet for a while"
          >
            ✕
          </button>
          <p class="in-flow-card__reason">{tool.reason}</p>
        </header>
        <ToolRenderer tool={tool} />
        {tool.notice && <p class="in-flow-card__notice">{tool.notice}</p>}
        <footer class="in-flow-card__foot">
          {tool.savedId ? (
            <span class="in-flow-quiet">In Your tools</span>
          ) : state.naming ? (
            <div class="in-flow-row">
              <input
                class="in-flow-input"
                placeholder={TOOL_LABELS[tool.kind]}
                value={state.name}
                onInput$={(_, el) => {
                  state.name = el.value;
                }}
                onKeyDown$={(event) => {
                  if (event.key === "Enter") void keep();
                  if (event.key === "Escape") state.naming = false;
                }}
                aria-label="Name for this tool"
              />
              <button
                type="button"
                class="btn-paper in-flow-mini"
                onClick$={keep}
              >
                Keep
              </button>
            </div>
          ) : (
            <button
              type="button"
              class="in-flow-link"
              onClick$={() => {
                state.naming = true;
                state.name = "";
              }}
              title="Save this tool, as you've set it up, to reuse on any passage"
            >
              Keep this tool
            </button>
          )}
          {state.keepError && (
            <p class="in-flow-card__notice" role="alert">
              {state.keepError}
            </p>
          )}
        </footer>
      </article>
    );

    return (
      <div ref={root} class="in-flow-rails" aria-live="polite">
        {state.shelf && (
          <aside class="in-flow-shelf" aria-label="Your tools">
            {/* The shelf appears once there is something on it; an empty
                placeholder would only push the writer's echoes down the
                margin. A tool card's "Keep this tool" introduces it. */}
            {state.saved.length > 0 && (
              <div class="in-flow-shelf__inner">
                <p class="in-flow-label">Your tools</p>
                <ul class="in-flow-shelf__list">
                  {state.saved.map((saved) => (
                    <li key={saved.id}>
                      <button
                        type="button"
                        class="in-flow-shelf__tool"
                        onClick$={() => inFlowController()?.openSaved(saved)}
                        title={`Use ${saved.name} on the paragraph you're in`}
                      >
                        <span>{saved.name}</span>
                        <small>{TOOL_LABELS[saved.kind]}</small>
                      </button>
                      <button
                        type="button"
                        class="in-flow-shelf__remove"
                        onClick$={() => void removeSavedTool(saved.id)}
                        aria-label={`Remove ${saved.name}`}
                      >
                        ✕
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {state.ticks.map((top) => (
              <span
                key={`tick-${top}`}
                class="in-flow-tick"
                style={{ top: `${top}px` }}
                aria-hidden="true"
              />
            ))}
          </aside>
        )}

        {tool && state.cardTop !== null && state.mode === "rail" && (
          <>
            <span
              class="in-flow-connector"
              style={{
                top: `${state.anchorTop + Math.min(12, state.anchorHeight / 2)}px`,
              }}
              aria-hidden="true"
            />
            <div
              class="in-flow-rail"
              style={{ top: `${state.cardTop}px`, width: `${CARD_WIDTH}px` }}
            >
              {card}
            </div>
          </>
        )}

        {tool && state.cardTop !== null && state.mode === "popover" && (
          <div
            class="in-flow-popover"
            style={{
              left: `${state.popLeft}px`,
              top: `${state.popTop}px`,
              width: `${CARD_WIDTH}px`,
            }}
          >
            {card}
          </div>
        )}
      </div>
    );
  },
);

src/utils/saved-tools.ts.content:
/**
 * Tools the writer chose to keep.
 *
 * A saved tool is a template — the kind plus whatever the writer tuned — and
 * never the passage it was first used on, so it travels between pieces
 * without carrying one draft's words into another. Stored once for the
 * writer, not per folio.
 */
import { loadMetaFromIdb, saveMetaToIdb } from "./idb";
import { TOOL_KINDS, type ToolKind } from "./struggle-signals";

export interface SavedToolConfig {
  /** Rhythm Strip: the comfortable sentence-length band, in words. */
  targetMin?: number;
  targetMax?: number;
  /** Claim Check: the kinds of support to ask for. */
  slots?: string[];
  /** Reader Questions: the reader to imagine. */
  angle?: string;
}

export interface SavedTool {
  id: string;
  kind: ToolKind;
  name: string;
  config: SavedToolConfig;
  savedAt: number;
}

const KEY = "saved-tools";
const MAX_SAVED = 24;
export const SAVED_TOOLS_EVENT = "twyne:saved-tools";

let storage = { load: loadMetaFromIdb, save: saveMetaToIdb };
export function __setSavedToolsStorageForTests(adapter: typeof storage | null) {
  storage = adapter ?? { load: loadMetaFromIdb, save: saveMetaToIdb };
}

function strings(value: unknown, max: number): string[] | undefined {
  if (!Array.isArray(value)) return undefined;
  return value
    .filter((item): item is string => typeof item === "string" && !!item.trim())
    .map((item) => item.slice(0, 60))
    .slice(0, max);
}

function int(value: unknown, min: number, max: number): number | undefined {
  return typeof value === "number" && Number.isFinite(value)
    ? Math.min(max, Math.max(min, Math.round(value)))
    : undefined;
}

/** Plain data only — Qwik store proxies fail IndexedDB's structured clone. */
export function normalizeSavedTool(value: unknown): SavedTool | null {
  if (!value || typeof value !== "object") return null;
  const raw = value as Record<string, unknown>;
  if (typeof raw.id !== "string" || !raw.id) return null;
  if (!TOOL_KINDS.includes(raw.kind as ToolKind)) return null;
  const config = (raw.config ?? {}) as Record<string, unknown>;
  const clean: SavedToolConfig = {};
  const targetMin = int(config.targetMin, 1, 80);
  const targetMax = int(config.targetMax, 2, 120);
  if (targetMin !== undefined) clean.targetMin = targetMin;
  if (targetMax !== undefined) clean.targetMax = targetMax;
  const slots = strings(config.slots, 5);
  if (slots?.length) clean.slots = slots;
  if (typeof config.angle === "string" && config.angle.trim())
    clean.angle = config.angle.trim().slice(0, 200);
  return {
    id: raw.id,
    kind: raw.kind as ToolKind,
    name:
      typeof raw.name === "string" && raw.name.trim()
        ? raw.name.trim().slice(0, 60)
        : String(raw.kind),
    config: clean,
    savedAt: typeof raw.savedAt === "number" ? raw.savedAt : 0,
  };
}

export async function loadSavedTools(): Promise<SavedTool[]> {
  const value = await storage.load<unknown[]>(KEY);
  if (!Array.isArray(value)) return [];
  return value
    .map(normalizeSavedTool)
    .filter((tool): tool is SavedTool => tool !== null);
}

async function write(tools: SavedTool[]): Promise<void> {
  const plain = JSON.parse(JSON.stringify(tools)) as SavedTool[];
  await storage.save(KEY, plain);
  // The shared IDB helper absorbs failures; read back so a lost write is loud.
  const check = await loadSavedTools();
  if (check.length !== plain.length)
    throw new Error("Saved tools did not persist");
  window.dispatchEvent(new CustomEvent(SAVED_TOOLS_EVENT, { detail: check }));
}

export async function saveTool(
  tool: Omit<SavedTool, "id" | "savedAt">,
): Promise<SavedTool> {
  const saved = normalizeSavedTool({
    ...tool,
    id: `tool-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    savedAt: Date.now(),
  });
  if (!saved) throw new Error("That tool could not be saved");
  const tools = await loadSavedTools();
  await write([saved, ...tools].slice(0, MAX_SAVED));
  return saved;
}

export async function removeSavedTool(id: string): Promise<void> {
  const tools = await loadSavedTools();
  await write(tools.filter((tool) => tool.id !== id));
}
